-- Esquema MÍNIMO da Fase 5 (financeiro) para testes locais. Rodar após schema_secretaria.sql.
CREATE TABLE CONTA_BANCARIA (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, DOCUMENTO INT NOT NULL DEFAULT 0,
  NOSSO_NUMERO INT NOT NULL DEFAULT 0, AGENCIA VARCHAR(20), DIG_AGENCIA VARCHAR(5), CONTA VARCHAR(20), DIG_CONTA VARCHAR(5),
  CODIGO_CEDENTE VARCHAR(30), AUTORIZAR TINYINT(1) NULL, DATA_CADASTRO DATETIME, INSTRUCOES TEXT, TITULAR VARCHAR(200), CNPJ VARCHAR(20),
  BANCO VARCHAR(50), CARTEIRA VARCHAR(10), CARTEIRA_VARIACAO VARCHAR(10), OPERACAO VARCHAR(10), CODIGO_TRANSMISSAO VARCHAR(30),
  TIPO_REMESSA VARCHAR(10), ARQUIVO_REMESSA_NUM INT NOT NULL DEFAULT 0, GATEWAY_TOKEN_PROD VARCHAR(500), GATEWAY_TOKEN_HOMO VARCHAR(500),
  PAGSEGURO_EMAIL VARCHAR(200));
CREATE TABLE LISTA_SITUACAO_CP (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
CREATE TABLE LISTA_CATEGORIA_CP (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
CREATE TABLE CONTAS_PAGAR (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, LISTA_SITUACAO_CP_ID BIGINT NULL,
  LISTA_CATEGORIA_CP_ID BIGINT NULL, DATA_VENCIMENTO DATETIME, DATA_PAGAMENTO DATETIME, DESCRICAO VARCHAR(300), VALOR DECIMAL(10,2) NOT NULL,
  DATA_CADASTRO DATETIME NOT NULL);
CREATE TABLE CONTAS_FIXAS (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, LISTA_CATEGORIA_CP_ID BIGINT NULL,
  DIA_VENCIMENTO INT NOT NULL, DESCRICAO VARCHAR(300), VALOR DECIMAL(10,2) NOT NULL, DATA_CADASTRO DATETIME NOT NULL);
ALTER TABLE CONTAS_RECEBER ADD NOSSO_NUMERO VARCHAR(50), ADD ARQUIVO_REMESSA VARCHAR(50), ADD ARQUIVO_RETORNO VARCHAR(50),
  ADD TOKEN_BOLETOCLOUD VARCHAR(200), ADD TOKEN_CC VARCHAR(200), ADD PERIODO BIGINT NULL;

